import documentMetadata from './document-metadata';

export default {
  // ...
  'document-metadata': documentMetadata,
};
```

Evidence: `content-manager/server/src/services/index.ts:13,20`.

Utility to get services:

```ts
// content-manager/server/src/utils/index.ts
import DocumentMetadata from 'src/services/document-metadata';

export default {
  // ...
  'document-metadata': typeof DocumentMetadata;
}
```

And usage:

```ts
