```

Evidence:
- `content-manager/server/src/utils/index.ts` shows export of the service type (via grep result).
- Controllers below show use of `getService('document-metadata')`.

So any plugin controller or service that does `getService('document-metadata')` will be affected.

### 2.2 HTTP entrypoints that reach `document-metadata`

The Koa controllers for collection-types and single-types call a helper that in turn uses `document-metadata`.

#### 2.2.1 Controller metadata helper

```ts
// content-manager/server/src/controllers/utils/metadata.ts
import { getService } from '../../utils';
import { DocumentVersion, GetMetadataOptions } from '../../services/document-metadata';

export const formatDocumentWithMetadata = async (
  permissionChecker: any,
  uid: UID.ContentType,
  document: DocumentVersion,
  opts: GetMetadataOptions = {}
) => {
  const documentMetadata = getService('document-metadata');

  const serviceOutput = await documentMetadata.formatDocumentWithMetadata(uid, document, opts);

  let {
    meta: { availableLocales, availableStatus },
  } = serviceOutput;

  const metadataSanitizer = permissionChecker.sanitizeOutput;

  availableLocales = await async.map(
    availableLocales,
    async (localeDocument: AvailableLocaleDocument) => metadataSanitizer(localeDocument)
  );

  availableStatus = await async.map(
    availableStatus,
    async (statusDocument: AvailableStatusDocument) => metadataSanitizer(statusDocument)
  );

  return {
    ...serviceOutput,
    meta: {
      availableLocales,
      availableStatus,
    },
  };
};
```

Evidence: `content-manager/server/src/controllers/utils/metadata.ts:6-52`.

This uses `documentMetadata.formatDocumentWithMetadata`, which in turn calls the changed `getMetadata`:

```ts
// document-metadata service
async formatDocumentWithMetadata(uid, document, opts) {
  // ...
  const meta = await this.getMetadata(uid, document, opts);
  // ...
  return {
    data: { ...document, status: /* ... */ },
    meta,
  };
}
```

Evidence: `content-manager/server/src/services/document-metadata.ts:196-257`.

So any controller using `formatDocumentWithMetadata` is now indirectly affected by the new media population behavior.

#### 2.2.2 Collection-types controller

```ts
// content-manager/server/src/controllers/collection-types.ts
import { formatDocumentWithMetadata } from './utils/metadata';
// ...

export default {
  async find(ctx: any) { /* ... */ },

  async findOne(ctx: any) {
    const { userAbility } = ctx.state;
    const { model, id } = ctx.params;
    // ...
    const version = await documentManager.findOne(id, model, { populate, locale, status });

    if (!version) {
      // Check if document exists
      const exists = await documentManager.exists(model, id);
      if (!exists) {
        return ctx.notFound();
      }

      // If the requested locale doesn't exist, return an empty response
      const { meta } = await formatDocumentWithMetadata(
        permissionChecker,
        model,
        // @ts-expect-error TODO: fix
        { documentId: id, locale, publishedAt: null },
        { availableLocales: true, availableStatus: false }
      );

      ctx.body = { data: {}, meta };
      return;
    }

    // ...
    const sanitizedDocument = await permissionChecker.sanitizeOutput(version);
    ctx.body = await formatDocumentWithMetadata(permissionChecker, model, sanitizedDocument);
  },

  async create(ctx: any) {
    // ...
    ctx.body = await formatDocumentWithMetadata(permissionChecker, model, sanitizedDocument, {
      availableLocales: false,
      availableStatus: false,
    });
  },

  async update(ctx: any) {
    // ...
    ctx.body = await formatDocumentWithMetadata(permissionChecker, model, sanitizedVersion);
  },

  async clone(ctx: any) {
    // ...
    ctx.body = await formatDocumentWithMetadata(permissionChecker, model, sanitizedDocument, {
      availableLocales: false,
      availableStatus: false,
    });
  },

  async publish(ctx: any) {
    // ...
    const sanitizedDocument = await permissionChecker.sanitizeOutput(publishedDocument);
    ctx.body = await formatDocumentWithMetadata(permissionChecker, model, sanitizedDocument);
  },

  async unpublish(ctx: any) {
    // inside transaction:
    ctx.body = await async.pipe(
      (document) => documentManager.unpublish(document.documentId, model, { locale }),
      permissionChecker.sanitizeOutput,
      (document) => formatDocumentWithMetadata(permissionChecker, model, document)
    )(document);
  },

  async discard(ctx: any) {
    ctx.body = await async.pipe(
      (document) => documentManager.discardDraft(document.documentId, model, { locale }),
      permissionChecker.sanitizeOutput,
      (document) => formatDocumentWithMetadata(permissionChecker, model, document)
    )(document);
  },
};
```

Evidence:
- `formatDocumentWithMetadata` import and uses at `content-manager/server/src/controllers/collection-types.ts:9, 111, 148, 190, 225, 311, 350`.

**HTTP routes:** These handlers back the admin API endpoints such as:

- `GET /content-manager/collection-types/:model/:id` (findOne)
- `POST /content-manager/collection-types/:model` (create)
- `PUT /content-manager/collection-types/:model/:id` (update)
- `POST /content-manager/collection-types/:model/clone/:sourceId` (clone)
- `POST /content-manager/collection-types/:model/:id/actions/publish` (publish)
- `POST /content-manager/collection-types/:model/:id/actions/unpublish` (unpublish)
- `POST /content-manager/collection-types/:model/:id/actions/discard` (discard)

The route mapping isn’t shown in the provided files, but the admin client uses exactly these paths (see below), so the controllers are the server entrypoints.

